List<int> intersperse(List<int> numbers, int delimiter) {
  if (numbers.isEmpty) return [];

  List<int> result = [numbers.first];

  for (int i = 1; i < numbers.length; i++) {
    result.add(delimiter);
    result.add(numbers[i]);
  }

  return result;
}

