List<int> intersperse(List<int> numbers, int delimiter) {
  List<int> result = [];

  for (int i = 0; i < numbers.length - 1; i++) {
    result.add(numbers[i]);
    result.add(delimiter);
  }

  // Add the last element without appending the delimiter again.
  if (numbers.isNotEmpty) {
    result.add(numbers.last);
  }

  return result;
}

