List<int> rollingMax(List<int> numbers) {
  if (numbers.isEmpty) return [];

  List<int> result = [];
  int maxSoFar = numbers[0];

  for (int num in numbers) {
    if (num > maxSoFar) {
      maxSoFar = num;
    }
    result.add(maxSoFar);
  }

  return result;
}

