import 'dart:math';

String stringXor(String a, String b) {
  if (a.length != b.length) throw ArgumentError('Strings must be of equal length');

  final xorBuilder = StringBuffer();
  for (int i = 0; i < a.length; ++i) {
    bool bitA = int.parse(a[i]) == 1;
    bool bitB = int.parse(b[i]) == 1;

    // XOR logic
    xorBuilder.write(bitA ^ bitB ? '1' : '0');
  }

  return xorBuilder.toString();
