String stringXor(String a, String b) {
  if (a.length != b.length)
    throw ArgumentError('Strings must be of equal length');

  StringBuffer result = new StringBuffer();

  for (int i = 0; i < a.length; ++i) {
    int bitA = int.parse(a[i]);
    int bitB = int.parse(b[i]);

    // Perform bitwise XOR operation on corresponding bits.
    bool xorResult = ((bitA ^ bitB)) == 1;

    // Append '1' or '0'.
    result.write(xorResult ? "1" : "0");
  }

  return result.toString();
}

