List<int> unique(List<int> l) {
  var growable = List.of(l)..sort();

  for (int i = 1; i < growable.length;) {
    if (growable[i] == growable[i - 1]) {
      // Remove the duplicate
      growable.removeAt(i);

      continue;
    }

    ++i;
  }

return growable.toList();

}

