bool triplesSumToZero(List<int> l) {
  if (l.length < 3) return false;

  for (int i = 0; i <= l.length - 2; ++i)
    for (int j = i + 1; j <= l.length - 1; ++j)
      for (int k = j + 1; k < l.length; ++k)
        if ((l[i] == -(l[j] + l[k])) ||
            (l[j] == -(l[i] + l[k])) ||
            (l[k] == -(l[i] + l[j])))
          return true;

  return false;
}

