bool triplesSumToZero(List<int> l) {
  if (l.length < 3 || l.isEmpty) return false;

  // Sort the list to simplify finding triplets.
  final sortedList = List.from(l)..sort();

  for (int i = 0; i <= sortedList.length - 3; ++i) {
    int leftIndex = i + 1;
    int rightIndex = sortedList.length - 1;

    while (leftIndex < rightIndex) {
      var sumOfTriple =
          sortedList[i] +
              sortedList[leftIndex] +
              sortedList[rightIndex];

      if (sumOfTriple == 0)
        return true;

      else if (sumOfTriple > 0) --rightIndex;
      else ++leftIndex;
    }
  }

  return false;
}

