import 'dart:math';

int largestPrimeFactor(int n) {
  if (n <= 1) return -1; // No prime factors for numbers less than or equal to 1

  int maxPrime = 0;

  while (n % 2 == 0) {
    maxPrime = 2;
    n ~/= 2;
  }

  for (int i = 3; i * i <= n; i += 2) {
    while (n % i == 0) {
      maxPrime = i;
      n ~/= i;
    }
  }

  if (n > 2) {
    maxPrime = n;
  }

  return maxPrime;
}

