bool correctBracketing(String brackets) {
  int balance = 0;

  for (int i = 0; i < brackets.length; i++) {
    if (brackets[i] == '(') {
      balance++;
    } else if (brackets[i] == ')') {
      if (--balance < 0) return false;
    }
  }

  // Check that all opening parentheses have been closed.
  return balance == 0;
}

