import 'dart:math';

List<int> maximum(List<int> arr, int k) {
  List<int>.from(arr..sort((a, b) => a.compareTo(b)));

  if (k == null || k <= 0 || k > arr.length) return [];

  final result = <int>[];
  for (var i = arr.length - 1; i >= arr.length - k && i >= 0 ; --i)
    result.add(arr[i]);

  // Reverse to maintain original order of largest numbers in input list.
  return result.reversed.toList();
}

